SysDataModelXML.SQLUpdateScript:
--根据STKLOTLST本地导入的记录，生成待提交STKBUS DECLARE @BATCHID VARCHAR(50) = '#LINKID_ACTION#'; DECLARE @USER VARCHAR(30) = '#LOGIN_USER#'; DECLARE @FAC VARCHAR(30) = '{0}'; --参数 DECLARE @WH VARCHAR(30) = '{1}'; --参数 DECLARE @LOC VARCHAR(30) = '{2}'; --参数
INSERT INTO [STKBUS] ([DOCTYP] ,[DOCNUM] ,[SITE] ,[ITMNO] ,[ITMVER] ,LOT ,SUBLOT ,PRJNUM ,BPRNO ,STA ,[FAC] ,[WH] ,[LOC] ,[UOM] ,[UOMCOE] ,[QTY] ,[QTYSTU] ,[STU] ,CTRNUM ,CTRQTY ,[WEIQTY] ,[TRXSIGN] ,[SRCTYP] ,[SRCDOC] ,[SRCLIN] ,SRCSEQ ,ORITYP ,ORIDOC ,ORILIN ,ORISEQ ,BATCHID ,[CREUSR] ,[CRETIM]) SELECT T.DOCTYP DOCTYP ,''DOCNUM ,T.[SITE] ,T.ITMNO ,T.ITMVER ,T.LOT ,T.SUBLOT ,'' PRJNUM ,T.BPRNO ,'A' STA ,@FAC FAC --参数 ,@WH WH --参数 ,@LOC LOC --参数 ,'BOX' --T.STU --T.UOM ,SUM(T.QTYSTU)/IIF(COUNT(TAGNO)=0,1,COUNT(TAGNO)) --1 --AVG(T.UOMCOE) UOMCOE --AVG ,IIF(COUNT(TAGNO)=0,1,COUNT(TAGNO)) --SUM(T.QTYSTU) QTY --sum ,SUM(T.QTYSTU) QTYSTU --sum ,T.STU ,IIF(COUNT(TAGNO)=0,1,COUNT(TAGNO)) ,SUM(T.QTYSTU)/IIF(COUNT(TAGNO)=0,1,COUNT(TAGNO)) ,SUM(T.RECWT) WEIQTY --确认 --sum ,1 TRXSIGN ,T.SRCTYP ,T.SRCDOC ,T.SRCLIN ,T.SRCSEQ ,T.ORITYP ,T.ORIDOC ,T.ORILIN ,T.ORISEQ ,@BATCHID BATCHID ,@USER [CREUSR] ,GETDATE() [CRETIM] FROM STKLOTLST T WITH(NOLOCK) WHERE T.CREUSR = @USER AND T.SUBSTA <> 3 -- 只处理 SUBSTA <> 3 的记录，处理完成功为3，失败为2 AND T.DOCSTA = 1 -- 只处理 DOCSTA = 1 的记录，处理完更新为 2 AND DOCTYP = 'PRC' AND DOCGRP = 'IMP' GROUP BY T.DOCTYP ,T.[SITE] ,T.[ITMNO] ,T.[ITMVER] ,T.BPRNO ,T.[LOT] ,T.[SUBLOT] ,T.UOM ,T.STU ,T.SRCTYP ,T.SRCDOC ,T.SRCLIN ,T.SRCSEQ ,T.ORITYP ,T.ORIDOC ,T.ORILIN ,T.ORISEQ;
-- 将数据汇总到STKBUS之后，标记 DOCSTA = 2, 防止重复处理 UPDATE STKLOTLST WITH (ROWLOCK) SET DOCSTA = 2, BATCHID = @BATCHID WHERE CREUSR = @USER AND SUBSTA <> 3 -- 只处理 SUBSTA <> 3 的记录，处理完成功为3，失败为2 AND DOCTYP = 'PRC' AND DOCGRP = 'IMP'
